def page(meta):
    k=meta['key']
    strip='<div class="demo-strip"><span><b>'+meta['title']+'</b> / '+meta['subtitle']+'</span><span class="extra">设计提案 · 固定合成数据 · 可交互</span></div>'
    if k=='impeccable':
        content='<div class="app">'+sidebar()+'<div>'+strip+topbar()+'<main class="main" id="main">'+pagehead(k)+'<div class="workspace"><div class="left-stack">'+chart(True)+JOBS+'</div><div class="right-stack">'+CONFIG+preflight()+'</div></div>'+FOOTER+'</main></div></div>'
    elif k=='pro':
        content=strip+topbar(True)+'<main class="main" id="main">'+pagehead(k)+METRICS+'<div class="workspace">'+chart()+preflight()+'</div><div class="bottom-grid">'+CONFIG+JOBS+'</div>'+FOOTER+'</main>'
    elif k=='taste':
        content='<div class="app">'+sidebar()+'<div>'+strip+topbar()+'<main class="main" id="main">'+pagehead(k)+'<div class="hero-divider"></div><div class="workspace">'+CONFIG+'<div class="right-stack">'+chart()+preflight()+'</div></div>'+METRICS+JOBS+FOOTER+'</main></div></div>'
    else:
        content=strip+topbar(True)+'<main class="main" id="main">'+pagehead(k)+'<div class="workspace"><div class="left-stack">'+METRICS+chart()+JOBS+'</div><div class="right-stack">'+CONFIG+preflight()+'</div></div>'+FOOTER+'</main>'
    return '<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="'+('dark' if k=='anthropic' else 'light')+'"><title>Quant Studio — '+meta['title']+'</title><style>'+CSS+'</style></head><body class="'+k+'" data-demo="'+k+'"><a class="skip" href="#main">跳到研究工作区</a>'+content+DIALOG+'<script>'+JS+'</script></body></html>'

for m in META:
    html=page(m)
    (OUT/m['file']).write_text(html,encoding='utf-8')
print('Built four standalone demos in',OUT)

